        [BLOCK.FLOWER_DANDELION]: 0.05,
        [BLOCK.OAK_SAPLING]: 0.05,
        [BLOCK.APPLE]: 0.05,
        [BLOCK.LEAVES]: 0.25,
        [BLOCK.DIRT]: 0.55,
        [BLOCK.GRASS]: 0.6,
        [BLOCK.SAND]: 0.55,
        [BLOCK.WOOD_PLANKS]: 1.1,
        [BLOCK.WOOD_LOG]: 1.35,
        [BLOCK.COBBLESTONE]: 1.8,
        [BLOCK.STONE]: 2.0,
        [BLOCK.COAL_ORE]: 2.2,
        [BLOCK.IRON_ORE]: 2.5,
        [BLOCK.DIAMOND_ORE]: 3.0,
        [BLOCK.CRAFTING_TABLE]: 1.2,
        [BLOCK.TORCH]: 0.05,
        [BLOCK.END_STONE]: 1.6,
        [BLOCK.EMERALD_ORE]: 3.0,
        [BLOCK.GLASS]: 0.4,
        [BLOCK.GRAVEL]: 0.65,
        [BLOCK.FARMLAND]: 0.6,
        [BLOCK.FARMLAND_WET]: 0.6,
        [BLOCK.WOOL]: 0.6,
        [BLOCK.BED_FOOT]: 0.3,
        [BLOCK.BED_HEAD]: 0.3,
        [BLOCK.BED_YELLOW_FOOT]: 0.3, [BLOCK.BED_YELLOW_HEAD]: 0.3, [BLOCK.BED_PINK_FOOT]: 0.3, [BLOCK.BED_PINK_HEAD]: 0.3,
        [BLOCK.FURNACE]: 2.0,
        [BLOCK.CHEST]: 1.3,
