            const t = this.ctx.currentTime;
            const o = this.ctx.createOscillator();
            o.type = 'triangle';
            o.frequency.setValueAtTime(180 + power * 160, t);
            o.frequency.exponentialRampToValueAtTime(70, t + 0.18);
